.button-container {
  display: flex;
  justify-content: center;
  gap: 20px;
}

/* Common styles for both buttons */
.brutalist-button {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  width: 142px;
  height: 142px;
  color: #e5dede;
  font-weight: bold;
  text-decoration: none;
  position: relative;
  cursor: pointer;
  overflow: hidden;
  transition: all 0.3s cubic-bezier(0.25, 0.8, 0.25, 1);
}

/* Styles for the first button */
.button-1 {
  background-color: #0000003f;
  border-top: 4px outset #f6821f;
  border-left: 4px outset #f6821f;
  border-right: 4px inset #f6821f;
  border-bottom: 4px inset#f6821f;
  border-radius: 12px;
}

.button-1:hover {
  background-color: #000000;
  border-color: #ff6a00;
}
@keyframes color-change {
  0% {
    color: #ffffff;
  }
  33% {
    color: #ff6a00;
  }
  66% {
    color: #ff6600f9;
  }
  90% {
    color: #ff6a00;
  }
  100% {
    color: #ffffff;
  }
}
.button-1::before,
.button-1::after {
  content: "";
  position: absolute;
  top: 0;
  width: 100%;
  height: 100%;
  background: linear-gradient(
    90deg,
    transparent,
    rgba(255, 255, 255, 0.1),
    transparent
  );
  transition: 0.6s;
}

cloudflare-logo {
  position: flex;
  align-self: top;
  padding-bottom: 200px;
  margin-top: 300px;
}

.button-1::before {
  left: 100%;
}
.button-1::after {
  left: 100%;
}

.button-1:hover::before {
  animation: swipeRight 1.5s infinite;
}
.button-1:hover::after {
  animation: swipeLeft 1.5s infinite;
}

@keyframes swipeRight {
  100% {
    transform: translateX(200%) skew(-45deg);
  }
}

@keyframes swipeLeft {
  100% {
    transform: translateX(-200%) skew(-45deg);
  }
}

/* Hover effects */

/* Styles for the OpenAI logo and text */

.button-text {
  display: flex;
  align-items: center;
  text-align: center;
  color: #ffffff;
  overflow: hidden;

  z-index: 3;
}

/* Hover effects */

.brutalist-button:hover .button-text {
  opacity: 1;
  max-height: 60px;
  margin-top: 8px;
  animation: color-change 2s ease-in-out infinite;
  transition: all 0.3s cubic-bezier(0.25, 0.8, 0.25, 1);
}
